using UnityEngine;

namespace Hindsight.EyeCanDo.UI
{
    /// <summary>Sound effect clips, generated by the builder into Resources/SoundLibrary.asset.</summary>
    [CreateAssetMenu(menuName = "EyeCanDo/Sound Library", fileName = "SoundLibrary")]
    public sealed class SoundLibrary : ScriptableObject
    {
        [Tooltip("One clip per SfxId, in enum order.")]
        [SerializeField] AudioClip[] clips = new AudioClip[0];
        [Tooltip("Loudness per clip, in enum order (0-1).")]
        [SerializeField] float[] volumes = new float[0];

        public AudioClip Get(SfxId id) => (int)id < clips.Length ? clips[(int)id] : null;
        public float VolumeOf(SfxId id) => (int)id < volumes.Length ? volumes[(int)id] : 1f;

#if UNITY_EDITOR
        public void EditorInit(AudioClip[] value, float[] loudness)
        {
            clips = value;
            volumes = loudness;
        }
#endif
    }
}
